import asyncio
import inspect
from functools import partial, wraps
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
from fastapi.dependencies.models import Dependant

def is_async_callable(call):
    # This is a simplified version of what FastAPI does internally
    # We want to see if FastAPI's Dependant would consider it async
    dep = Dependant(call=call)
    return dep.is_coroutine_callable

async def async_func():
    return "async"

def sync_func():
    return "sync"

def wrap_sync(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper

async def wrap_async(f):
    # This is a bit tricky because wrap_async itself is async, 
    # but it returns a function.
    # Actually, usually a decorator is a function that returns a function.
    pass

def async_decorator(f):
    @wraps(f)
    async def wrapper(*args, **kwargs):
        return await f(*args, **kwargs) if asyncio.iscoroutinefunction(f) else f(*args, **kwargs)
    return wrapper

def sync_decorator(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper

def test_combinations():
    test_cases = [
        ("async_func", async_func, True),
        ("sync_func", sync_func, False),
        ("partial_async", partial(async_func), True),
        ("partial_sync", partial(sync_func), False),
        ("wrap_sync_sync", wrap_sync(sync_func), False),
        ("wrap_sync_async", wrap_sync(async_func), True),
        ("async_dec_sync", async_decorator(sync_func), True),
        ("async_dec_async", async_decorator(async_func), True),
        ("partial_wrap_sync_async", partial(wrap_sync(async_func)), True),
        ("wrap_sync_partial_async", wrap_sync(partial(async_func)), True),
        ("partial_async_dec_sync", partial(async_decorator(sync_func)), True),
        ("async_dec_partial_async", async_decorator(partial(async_func)), True),
    ]

    for name, call, expected in test_cases:
        actual = is_async_callable(call)
        print(f"{name}: expected {expected}, actual {actual}")
        assert actual == expected, f"{name} failed: expected {expected}, actual {actual}"

if __name__ == "__main__":
    try:
        test_combinations()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)

from fastapi import FastAPI
from fastapi.testclient import TestClient

