def _is_callable_type(call: Any, predicate: Callable[[Any], bool]) -> bool:
    while True:
        if call is None:
            return False
        if predicate(call):
            return True

        unwrapped = inspect.unwrap(call)
        if unwrapped is not call:
            call = unwrapped
            continue

        if isinstance(call, partial):
            call = call.func
            continue

        if not (inspect.isroutine(call) or inspect.isclass(call)):
            dunder_call = getattr(call, "__call__", None)
            if dunder_call and predicate(dunder_call):
                return True

        break
    return False


