import re
import time
from rich.cells import _is_single_cell_widths, set_cell_size

def test_regex():
    test_strings = ["hello", "world", "pqrstuvwxyz", "ABCDEFGHIJKLMNOPQRSTUVWXYZ", "1234567890", "!@#$%^&*()_+"]
    for s in test_strings:
        print(f"'{s}': {_is_single_cell_widths(s) is not None}")

def benchmark():
    s = "pqrstuvwxyz" * 10
    start = time.time()
    for _ in range(10000):
        set_cell_size(s, 10)
    print(f"Time: {time.time() - start:.4f}s")

if __name__ == '__main__':
    test_regex()
    benchmark()

from rich.cells import get_character_cell_size

def check_range(start, end):
    for i in range(start, end + 1):
        char = chr(i)
        if get_character_cell_size(char) != 1:
            print(f"Character {hex(i)} ({char!r}) has size {get_character_cell_size(char)}")

print("Checking 0x0020 to 0x02FF")
check_range(0x0020, 0x02FF)
print("Checking 0x0370 to 0x0482")
check_range(0x0370, 0x0482)

from fastapi import FastAPI, File, Form, UploadFile
