@app.post("/upload_1")
async def upload_1(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

@app.post("/upload_2")
async def upload_2(form_data: str = Form(...), file1: UploadFile = File(...), file2: UploadFile = File(...)):
    return {"form_data": form_data, "file1": file1.filename, "file2": file2.filename}

@app.post("/upload_3")
async def upload_3(form_data: str = Form(...), file: bytes = File(...)):
    return {"form_data": form_data, "file_len": len(file)}

client = TestClient(app)

def test_upload_1():
    response = client.post(
        "/upload_1",
        data={"form_data": "test value"},
        files={"file": ("test.txt", b"test content")}
    )
    print(f"upload_1: {response.status_code}, {response.text}")
