app = FastAPI()

@app.post("/upload_file_first")
async def upload_file_first(file: UploadFile = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file": file.filename}

@app.post("/upload_form_first")
async def upload_form_first(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

@app.post("/upload_form_first_bytes")
async def upload_form_first_bytes(form_data: str = Form(...), file: bytes = File(...)):
    return {"form_data": form_data, "file": len(file)}

client = TestClient(app)

def test_file_first():
    print("Testing /upload_file_first...")
    response = client.post(
        "/upload_file_first",
        data={"form_data": "test value"},
        files={"file": ("test.txt", b"test content")}
    )
    print(f"Response: {response.status_code}, Body: {response.json()}")
    assert response.status_code == 200

def test_form_first():
