from typing import Annotated
from fastapi import Depends, FastAPI
from fastapi.testclient import TestClient

app = FastAPI()

def get_foo(q: str = "default"):
    return q

# Partial of a plain function
partial_foo = functools.partial(get_foo, q="partial_value")

@app.get("/")
async def root(foo: Annotated[str, Depends(partial_foo)]):
    return {"foo": foo}

client = TestClient(app)

def test_partial_plain():
    response = client.get("/")
    assert response.json() == {"foo": "partial_value"}

async def get_bar(q: str = "default"):
    return q

# Partial of an async function
partial_bar = functools.partial(get_bar, q="partial_value")

@app.get("/bar")
async def bar_route(foo: Annotated[str, Depends(partial_bar)]):
    return {"foo": foo}

def test_partial_async():
    response = client.get("/bar")
    assert response.json() == {"foo": "partial_value"}

class CallableClass:
    def __call__(self, q: str = "default"):
        return q

# Partial of a callable class instance
callable_instance = CallableClass()
partial_callable = functools.partial(callable_instance, q="partial_value")

@app.get("/callable")
async def callable_route(foo: Annotated[str, Depends(partial_callable)]):
    return {"foo": foo}

def test_partial_callable():
    response = client.get("/callable")
    assert response.json() == {"foo": "partial_value"}

if __name__ == "__main__":
