    # I'll just call the functions.
    try:
        test_partial_plain()
        print("test_partial_plain passed")
    except Exception as e:
        print(f"test_partial_plain failed: {e}")

    try:
        # Need to run async test
        import asyncio
        asyncio.run(test_partial_async()) # Wait, test_partial_async is not async
    except Exception as e:
        print(f"test_partial_async failed: {e}")

    try:
        test_partial_callable()
        print("test_partial_callable passed")
    except Exception as e:
        print(f"test_partial_callable failed: {e}")

