import inspect
from functools import partial
import asyncio

def gen():
    yield 1

async def async_gen():
    yield 1

async def coro():
    return 1

class CallableClass:
    def __call__(self):
        return 1

class AsyncCallableClass:
    async def __call__(self):
        return 1

def is_gen(f):
    return inspect.isgeneratorfunction(f)

def is_async_gen(f):
    return inspect.isasyncgenfunction(f)

def is_coro(f):
    # Simplified version of iscoroutinefunction
    try:
        from asyncio import iscoroutinefunction
    except ImportError:
        from inspect import iscoroutinefunction
    return iscoroutinefunction(f)

