import asyncio
import inspect
from functools import wraps, partial
from fastapi.dependencies.models import Dependant

async def async_func():
    return "async"

def sync_func():
    return "sync"

def wrap_sync(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper

def wrap_async(f):
    @wraps(f)
    async def wrapper(*args, **kwargs):
        return await f(*args, **kwargs)
    return wrapper

def test_combinations():
    cases = [
        ("async_func", async_func, True),
        ("sync_func", sync_func, False),
        (f"wrap_sync(async_func)", wrap_sync(async_func), True),
        (f"wrap_async(sync_func)", wrap_async(sync_func), True),
        (f"wrap_sync(wrap_async(sync_func))", wrap_sync(wrap_async(sync_func)), True),
        (f"wrap_async(wrap_sync(async_func))", wrap_async(wrap_sync(async_func)), True),
        (f"partial(async_func)", partial(async_func), True),
        (f"partial(sync_func)", partial(sync_func), False),
        (f"partial(wrap_sync(async_func))", partial(wrap_sync(async_func)), True),
        (f"partial(wrap_async(sync_func))", partial(wrap_async(sync_func)), True),
        (f"wrap_sync(partial(async_func))", wrap_sync(partial(async_func)), True),
        (f"wrap_async(partial(sync_func))", wrap_async(partial(sync_func)), True),
    ]

    for name, call, expected in cases:
        dep = Dependant(call=call)
        result = dep.is_coroutine_callable
        print(f"{name}: expected {expected}, got {result}")
        assert result == expected, f"Failed for {name}"

if __name__ == "__main__":
    try:
        test_combinations()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Assertion failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

