import asyncio
import inspect
from functools import wraps, partial
from fastapi.dependencies.models import Dependant

async def async_func():
    return "async"

def sync_func():
    return "sync"

def wrapper(func):
    @wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

async def async_wrapper(func):
    @wraps(func)
    async def wrapped(*args, **kwargs):
        return await func(*args, **kwargs)
    return wrapped

# Case 1: async function wrapped by sync wrapper
# The wrapper is sync, but it calls an async function. 
# Wait, if the wrapper is sync, it can't await the async function.
# Usually, if you wrap an async function, the wrapper should also be async.

# Case 2: sync function wrapped by async wrapper
# The wrapper is async, but the wrapped function is sync.
# This should be treated as async because the wrapper is async.

def test_async_wrapper_sync_func():
    def sync_func():
        return "sync"

    async def async_wrapper_impl(func):
        @wraps(func)
        async def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    wrapped_func = asyncio.run(async_wrapper_impl(sync_func)) # This is wrong, async_wrapper_impl is async
    # Let's just define it normally

    async def wrapped_sync_func():
        return sync_func()

    # Now wrap it with wraps
    @wraps(sync_func)
    async def wrapped_sync_func_with_wraps():
        return sync_func()

    dep = Dependant(call=wrapped_sync_func_with_wraps)
    print(f"is_coroutine_callable: {dep.is_coroutine_callable}")
    # _unwrapped_call should be sync_func
    print(f"_unwrapped_call: {dep._unwrapped_call}")
    print(f"iscoroutinefunction(_unwrapped_call): {inspect.iscoroutinefunction(dep._unwrapped_call)}")

if __name__ == "__main__":
    test_async_wrapper_sync_func()

