    # Since we installed the excepthook, we need to trigger an unhandled exception
    # to see the output.
    try:
        try:
            raise ValueError("Original error")
        except ValueError as e:
            e.add_note("This is a note")
            raise e
    except Exception:
        # This will be caught by sys.excepthook (rich)
        # But we are in a script, so we might need to call the handler manually
        # or just let it crash.
        # To be sure it prints, we can use a Console and print the Traceback object.
        pass

