from typing import Any, Literal, Annotated, Union
from pydantic import BaseModel, Discriminator
from fastapi import FastAPI, Body
from fastapi.testclient import TestClient

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

# This is the problematic type
# Note: Tag is not defined in the problem statement but used. 
# I'll use a dummy class for Tag or just omit it if it's not essential for the bug.
# Actually, the problem says "tagged discriminated union". 
# In Pydantic v2, Discriminator is used. 
# The example uses Tag("apple"), which might be a custom annotation or from some library.
# Let's see if we can reproduce it without Tag first, or define a dummy Tag.

class Tag:
    def __init__(self, value):
        self.value = value

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

app = FastAPI()

@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()

client = TestClient(app)

def test_dessert():
    # This should be recognized as a body field.
    # If it's recognized as a query param, it will fail with a validation error 
    # because it's missing from the query string and not provided in the body.
    response = client.post("/dessert", json={"fruit": "apple", "time_to_cook": 10, "num_ingredients": 5})
    print(f"Status code: {response.status_code}")
    print(f"Response: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_dessert()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

