import asyncio
from functools import wraps, partial
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

app = FastAPI()

async def async_func():
    return "async_func"

def sync_func():
    return "sync_func"

def sync_wrapper(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def async_wrapper(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs) if asyncio.iscoroutinefunction(func) else func(*args, **kwargs)
    return wrapper

# Case 1: sync wrapper around async func
wrapped_async = sync_wrapper(async_func)
# Case 2: async wrapper around sync func
wrapped_sync = async_wrapper(sync_func)

@app.get("/case1")
async def case1(dep=Depends(wrapped_async)):
    return dep

@app.get("/case2")
async def case2(dep=Depends(wrapped_sync)):
    return dep

client = TestClient(app)

def test_case1():
    # wrapped_async is a sync function that returns a coroutine
    response = client.get("/case1")
    print(f"Case 1 response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == "async_func"

def test_case2():
    # wrapped_sync is an async function
    response = client.get("/case2")
    print(f"Case 2 response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == "sync_func"

if __name__ == "__main__":
    try:
        test_case1()
        print("Case 1 passed")
    except Exception as e:
        print(f"Case 1 failed: {e}")

    try:
        test_case2()
        print("Case 2 passed")
    except Exception as e:
        print(f"Case 2 failed: {e}")

