from rich.repr import auto
import inspect

class Foo:
    def __eq__(self, other):
        return True

@auto
class Bar:
    def __init__(self, x=Foo()):
        self.x = x

bar = Bar()
result = list(Bar.__rich_repr__(bar))
print(f"Result: {result}")

# Expected: [('x', bar.x, Foo())]
# Actual (if bug): [bar.x]
if len(result) == 1 and isinstance(result[0], tuple):
    print("SUCCESS: Correctly identified default value")
else:
