# Mocking Dependant for testing
from dataclasses import dataclass
from typing import Any, List, Optional

@dataclass
class MockDependant:
    call: Any = None

    @property
    def is_gen_callable(self) -> bool:
        if inspect.isgeneratorfunction(self.call):
            return True
        dunder_call = getattr(self.call, "__call__", None)
        return inspect.isgeneratorfunction(dunder_call)

    @property
    def is_async_gen_callable(self) -> bool:
        if inspect.isasyncgenfunction(self.call):
            return True
        dunder_call = getattr(self.call, "__call__", None)
        return inspect.isasyncgenfunction(dunder_call)

    @property
    def is_coroutine_callable(self) -> bool:
        if inspect.isroutine(self.call):
            # Using asyncio.iscoroutinefunction as in fastapi/dependencies/models.py
            from asyncio import iscoroutinefunction
            return iscoroutinefunction(self.call)
        if inspect.isclass(self.call):
            return False
        dunder_call = getattr(self.call, "__call__", None)
        from asyncio import iscoroutinefunction
        return iscoroutinefunction(dunder_call)

def test_reproduction():
    dep = MockDependant(call=get_settings)
    print(f"is_coroutine_callable: {dep.is_coroutine_callable}")
    assert dep.is_coroutine_callable is True, "Should be True even if wrapped"

if __name__ == "__main__":
    try:
        test_reproduction()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

